#include <stdio.h>
#include <math.h>
int main(){
    double points[8][2] = {{1,2},{1,4},{2,3},{5,8},{6,9},{5,7},{8,1},{9,2}};
    double c1[2] = {1,2}, c2[2] = {5,8};
    int assign[8];
    for(int i=0;i<8;i++){
        double d1 = pow(points[i][0]-c1[0],2)+pow(points[i][1]-c1[1],2);
        double d2 = pow(points[i][0]-c2[0],2)+pow(points[i][1]-c2[1],2);
        assign[i] = (d1<=d2)?1:2;
    }
    double sum1[2]={0,0}, sum2[2]={0,0};
    int cnt1=0,cnt2=0;
    for(int i=0;i<8;i++){
        if(assign[i]==1){sum1[0]+=points[i][0]; sum1[1]+=points[i][1]; cnt1++;}
        else {sum2[0]+=points[i][0]; sum2[1]+=points[i][1]; cnt2++;}
    }
    printf("C1' = (%.2f, %.2f)\n", sum1[0]/cnt1, sum1[1]/cnt1);
    printf("C2' = (%.2f, %.2f)\n", sum2[0]/cnt2, sum2[1]/cnt2);
    return 0;
}
